// Synthetic quotes and trades for two made-up symbols over 30 minutes, timestamps in ms.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(31);
const MINUTES = 30, END = MINUTES * 60 * 1000;
const quotes = [], trades = [];
for (const [symbol, start] of [['ACME', 50], ['BOLT', 120]]) {
  let mid = start, ts = 0, quoteId = 0;
  const cents = x => Math.round(x * 100) / 100;
  const book = [];                                   // this symbol's quotes, for the trades
  while ((ts += 50 + Math.floor(rand() * 500)) < END) {   // a new quote every 50 to 550 ms
    mid += (rand() - 0.5) * 0.02;
    const half = 0.01 * (1 + Math.floor(rand() * 3));      // spread of 2, 4 or 6 cents
    const q = { quote_id: ++quoteId, symbol, ts, bid: cents(mid - half), ask: cents(mid + half) };
    quotes.push(q); book.push(q);
  }
  let k = 0, tradeId = 0;
  ts = 0;
  while ((ts += 300 + Math.floor(rand() * 2400)) < END) {  // a trade every 0.3 to 2.7 s
    while (k + 1 < book.length && book[k + 1].ts <= ts) k++;
    const q = book[k];
    if (q.ts > ts) continue;                               // no quote yet
    const r = rand();                                      // at the ask, at the bid, or inside
    const price = r < 0.45 ? q.ask : r < 0.9 ? q.bid : cents((q.bid + q.ask) / 2);
    trades.push({ trade_id: symbol + '-' + (++tradeId), symbol, ts, price, qty: 100 * (1 + Math.floor(rand() * 10)) });
  }
}
nb.set('quotes', quotes);
nb.set('trades', trades);
console.log(quotes.length + ' quotes and ' + trades.length + ' trades over ' + MINUTES + ' minutes');
console.log('first quote: ' + JSON.stringify(quotes[0]));
console.log('first trade: ' + JSON.stringify(trades[0]));

-- How will SQLite find the latest quote at or before a trade? Ask it, before and after an index.
EXPLAIN QUERY PLAN
SELECT (SELECT bid FROM quotes q WHERE q.symbol = t.symbol AND q.ts <= t.ts ORDER BY q.ts DESC LIMIT 1)
FROM trades t;

CREATE INDEX IF NOT EXISTS quotes_by_symbol_time ON quotes (symbol, ts);

EXPLAIN QUERY PLAN
SELECT (SELECT bid FROM quotes q WHERE q.symbol = t.symbol AND q.ts <= t.ts ORDER BY q.ts DESC LIMIT 1)
FROM trades t;

// Redo the as-of match with a binary search per trade, and compare with the SQL.
const quotes = nb.get('quotes'), trades = nb.get('trades'), matched = nb.get('matched');
if (!quotes || !trades || !matched) return 'Run the cells above first.';

const bySymbol = {};
for (const q of quotes) (bySymbol[q.symbol] = bySymbol[q.symbol] || []).push(q);
for (const list of Object.values(bySymbol)) list.sort((a, b) => a.ts - b.ts);

// the last quote with ts <= t: binary search for the first quote after t, step back one
function asOf(symbol, t) {
  const list = bySymbol[symbol];
  let lo = 0, hi = list.length;
  while (lo < hi) { const mid = (lo + hi) >> 1; if (list[mid].ts <= t) lo = mid + 1; else hi = mid; }
  return lo ? list[lo - 1] : null;
}
const sqlByTrade = Object.fromEntries(matched.map(m => [m.trade_id, m.quote_id]));
let differ = 0, missing = 0;
for (const t of trades) {
  const q = asOf(t.symbol, t.ts);
  if (!(t.trade_id in sqlByTrade)) missing++;
  else if (!q || q.quote_id !== sqlByTrade[t.trade_id]) differ++;
}
console.log(trades.length + ' trades: SQL matched ' + matched.length + ', ' + missing + ' missing, ' + differ + ' matched to a different quote');

const ages = matched.map(m => m.quote_age_ms).sort((a, b) => a - b);
const pct = p => ages[Math.min(ages.length - 1, Math.floor(p / 100 * ages.length))];
console.log('quote age at the trade: median ' + pct(50) + ' ms, 90th percentile ' + pct(90) + ' ms, oldest ' + ages.at(-1) + ' ms');

const bins = [];
for (let lo = 0; lo < 600; lo += 25) bins.push({ lo, hi: lo + 25, trades: ages.filter(a => a >= lo && a < lo + 25).length });
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 220,
  title: 'How old was the quote each trade was matched to?',
  data: { values: bins },
  mark: { type: 'bar', color: '#3b82f6' },
  encoding: {
    x: { field: 'lo', type: 'quantitative', bin: { binned: true, step: 25 }, title: 'quote age at the trade (ms)' },
    x2: { field: 'hi' },
    y: { field: 'trades', type: 'quantitative' },
  },
};
